import{_ as r,a0 as a,w as i,s,ao as d,I as e,x as t,a1 as l,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/20 - The history of Android","title":"安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/20 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/20 - The history of Android.md"};function m(g,o,f,y,T,A){const n=a("Link");return i(),s("div",null,[o[25]||(o[25]=d('<h1 id="安卓編年史-19-android-4-0-冰淇淋三明治—摩登時代" tabindex="-1">安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代 <a class="header-anchor" href="#安卓編年史-19-android-4-0-冰淇淋三明治—摩登時代" aria-label="Permalink to “安卓編年史（19）：Android 4.0 冰淇淋三明治—摩登時代”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/market-pages.png" alt="和之前完全不同的市場設計。以上是分類，特色，熱門應用以及應用詳情頁面。"></p><p><em>和之前完全不同的市場設計。以上是分類，特色，熱門應用以及應用詳情頁面。 [Ron Amadeo 供圖]</em></p><p>這些截圖給了我們冰淇淋三明治中新版操作欄的第一印象。幾乎所有的應用頂部都有一條欄，帶有應用圖標，當前界面標題，一些功能按鈕，右邊還有一個菜單按鈕。這個右對齊的菜單按鈕被稱為“更多操作”，因為裏面存放着無法放置到主操作欄的項目。不過更多操作菜單並不是固定不變的，它給了操作欄節省了更多的屏幕空間——比如在橫屏模式或在平板上時，更多操作菜單的項目會像通常的按鈕一樣顯示在操作欄上。</p><p>冰淇凌三明治中新增了“滑動標籤頁”設計，替換掉了谷歌之前推行的 2×3 方陣導航屏幕。一個標籤頁欄放置在了操作欄下方，位於中間的標籤顯示的是當前頁面，左右側的兩個標籤顯示的是對應的當前頁面的左右側頁面。向左右滑動可以切換標籤頁，或者你可以點擊指定頁面的標籤跳轉過去。</p><p>應用詳情頁面有個很讚的設計，在應用截圖後，會根據你關於那個應用的歷史動態地重新佈局頁面。如果你從來沒有安裝過該應用，應用描述會優先顯示。如果你曾安裝過這個應用，第一部分將會是評價欄，它會邀請你評價該應用或者提醒你上次你安裝該應用時的評價是什麼。之前使用過的應用頁面第二部分是“新特性”，因為一個老用户最關心的應該是應用有什麼變化。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/recentbrowser.png" alt="最近應用和瀏覽器和蜂巢中的類似，但是是小號的"></p><p><em>最近應用和瀏覽器和蜂巢中的類似，但是是小號的。 [Ron Amadeo 供圖]</em></p><p>最近應用的電子風格外觀被移除了。略縮圖周圍的藍色的輪廓線被去除了，同時去除的還有背景怪異的、不均勻的藍色光暈。它現在看起來是個中立型的界面，在任何時候看起來都很舒適。</p><p>瀏覽器盡了最大的努力把標籤頁體驗帶到手機上來。多標籤瀏覽受到了關注，操作欄上引入的一個標籤頁按鈕會打開一個類似最近應用的界面，顯示你打開的標籤頁，而不是浪費寶貴的屏幕空間引入一個標籤條。從功能上來説，這個和之前的瀏覽器中的“窗口”視圖沒什麼差別。瀏覽器最佳的改進是菜單中的“請求桌面版站點”選項，這讓你可以從默認的移動站點視圖切換到正常站點。瀏覽器展示了谷歌的操作欄設計的靈活性，儘管這裏沒有左上角的應用圖標，功能上來説和其他的頂欄設計相似。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/gmail2.png" alt="Gmail 和 Google Talk —— 它們和蜂巢中的相似，但是更小！"></p><p><em>Gmail 和 Google Talk —— 它們和蜂巢中的相似，但是更小！ [Ron Amadeo 供圖]</em></p><p>Gmail 和 Google Talk 看起來都像是之前蜂巢中的設計的縮小版，但是有些小調整讓它們在小屏幕上表現更佳。Gmail 以雙操作欄為特色——一個在屏幕頂部，一個在底部。頂部操作欄顯示當前文件夾、賬户，以及未讀消息數目，點擊頂欄可以打開一個導航菜單。底部操作欄有你期望出現在更多操作中的選項。使用雙操作欄佈局是為了在界面顯示更多的按鈕，但是在橫屏模式下縱向空間有限，雙操作欄就合併成一個頂部操作欄。</p><p>在郵件視圖下，往下滾動屏幕時藍色欄有“粘性”。它會固定在屏幕頂部，所以你一直可以看到該郵件是誰寫的，回覆它，或者給它加星標。一旦處於郵件消息界面，底部細長的、深灰色欄會顯示你當前在收件箱（或你所在的某個列表）的位置，並且你可以向左或向右滑動來切換到其他郵件。</p><p>Google Talk 允許你像在 Gmail 中那樣左右滑動來切換聊天窗口，但是這裏顯示欄是在頂部。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/inc-calls.png" alt="新的撥號和來電界面，都是薑餅以來我們還沒見過的。"></p><p><em>新的撥號和來電界面，都是薑餅以來我們還沒見過的。 [Ron Amadeo 供圖]</em></p><p>因為蜂巢只給平板使用，所以一些界面設計直接超前於薑餅。冰淇淋三明治的新撥號界面就是如此，黑色和藍色相間，並且使用了可滑動切換的小標籤。儘管冰淇淋三明治終於做對了，將電話主體和聯繫人獨立開來，但電話應用還是有它自己的聯繫人標籤。現在有兩個地方可以看到你的聯繫人列表——一個有着暗色主題，另一個有着亮色主題。由於實體搜索按鈕不再是硬性要求，底部的按鈕欄的語音信息快捷方式被替換為了搜索圖標。</p><p>谷歌幾乎就是把來電界面做成了鎖屏界面的鏡像，這意味着冰淇淋三明治有着一個環狀解鎖設計。除了通常的接受和掛斷選項，圓環的頂部還添加了一個按鈕，讓你可以掛斷來電並給對方發送一條預先定義好的信息。向上滑動並選擇一條信息如“現在無法接聽，一會回電”，相比於一直響個不停的手機而言這樣做的信息交流更加豐富。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/thenonmessedupversion.png" alt="蜂巢沒有文件夾和信息應用，所以這裏是冰淇淋三明治和薑餅的對比。"></p><p><em>蜂巢沒有文件夾和信息應用，所以這裏是冰淇淋三明治和薑餅的對比。 [Ron Amadeo 供圖]</em></p><p>現在創建文件夾更加方便了。在薑餅中，你得長按屏幕，選擇“文件夾”選項，再點擊“新文件夾”。在冰淇淋三明治中，你只要將一個圖標拖拽到另一個圖標上面，就會自動創建一個文件夾，並包含這兩個圖標。這簡直不能更簡單了，比尋找隱藏的長按命令容易多了。</p><p>設計上也有很大的改進。薑餅使用了一個通用的米黃色文件夾圖標，但冰淇淋三明治直接顯示出了文件夾中的頭三個應用，把它們的圖標疊在一起，在外側畫一個圓圈，並將其設置為文件夾圖標。打開文件夾容器將自動調整大小以適應文件夾中的應用圖標數目，而不是顯示一個全屏的，大部分都是空的對話框。這看起來好得多得多。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/youtubes.png" alt="Youtube 轉換到一個更加現代的白色主題，使用了列表視圖替換瘋狂的 3D 滾動視圖。"></p><p><em>Youtube 轉換到一個更加現代的白色主題，使用了列表視圖替換瘋狂的 3D 滾動視圖。 [Ron Amadeo 供圖]</em></p><p>Youtube 經過了完全的重新設計，看起來沒那麼像是來自黑客帝國的產物，更像是，嗯，Youtube。它現在就是一個簡單的垂直滾動的白色視頻列表，就像網站的那樣。在你手機上製作視頻受到了重視，操作欄的第一個按鈕專用於拍攝視頻。奇怪的是，不同的界面左上角使用了不同的 Youtube 標誌，在水平的 Youtube 標誌和方形標誌之間切換。</p><p>Youtube 幾乎在所有地方都使用了滑動標籤頁。它們被放置在主頁面以在瀏覽和賬户間切換，放置在視頻頁面以在評論，介紹和相關視頻之間切換。4.0 版本的應用顯示出 Google+ Youtube 集成的第一個信號，通常的評分按鈕旁邊放置了 “+1” 圖標。最終 Google+ 會完全佔據 Youtube，將評論和作者頁面變成 Google+ 活動。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/data.png" alt="冰淇淋三明治試着讓事情對所有人都更加簡單。這裏是數據使用量追蹤，打開許多數據的新開發者選項，以及使用嚮導。"></p><p><em>冰淇淋三明治試着讓事情對所有人都更加簡單。這裏是數據使用量追蹤，打開許多數據的新開發者選項，以及使用嚮導。 [Ron Amadeo 供圖]</em></p><p>數據使用量允許用户更輕鬆地追蹤和控制他們的數據使用。主頁面顯示一個月度使用量圖表，用户可以設置數據使用警告值或者硬性使用限制以避免超量使用產生費用。所有的這些只需簡單地拖動橙色和紅色水平限制線在圖表上的位置即可。縱向的白色把手允許用户選擇圖表上的一段指定時間段。在頁面底部，選定時間段內的數據使用量又細分到每個應用，所以用户可以選擇一個數據使用高峯並輕鬆地查看哪個應用在消耗大量流量。當流量緊張的時候，更多操作按鈕中有個限制所有後台流量的選項。設置之後只用在前台運行的程序有權連接互聯網。</p><p>開發者選項通常只有一點點設置選項，但是在冰淇淋三明治中，這部分有非常多選項。谷歌添加了所有類型的屏幕診斷顯示浮層來幫助開發者理解他們的應用中發生了什麼。你可以看到 CPU 使用率，觸摸點位置，還有視圖界面更新。還有些選項可以更改系統功能，比如控制動畫速度，後台處理，以及 GPU 渲染。</p><p>安卓和 iOS 之間最大的區別之一就是應用抽屜界面。在冰淇淋三明治對更加用户友好的追求下，設備第一次初始化啓動會啓動一個小教程，向用户展示應用抽屜的位置以及如何將應用圖標從應用抽屜拖拽到主屏幕。隨着實體菜單按鍵的移除和像這樣的改變，安卓 4.0 做了很大的努力變得對新智能手機用户和轉換過來的用户更有吸引力。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/2014-03-06-03.57.png" alt="“觸摸分享”NFC 支持，Google Earth，以及應用信息，讓你可以禁用垃圾軟件。"></p><p><em>“觸摸分享”NFC 支持，Google Earth，以及應用信息，讓你可以禁用垃圾軟件。</em></p>',34)),e("p",null,[o[1]||(o[1]=t("冰淇淋三明治內置對 ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[0]||(o[0]=[t("NFC",-1)])]),_:1}),o[2]||(o[2]=t(" 的完整支持。儘管之前的設備，比如 Nexus S 也擁有 NFC，得到的支持是有限的並且系統並不能利用芯片做太多事情。4.0 添加了一個“Android Beam”功能，兩台擁有 NFC 的安卓 4.0 設備可以藉此在設備間來回傳輸數據。NFC 會傳輸關於此時屏幕顯示的數據，因此在手機顯示一個網頁的時候使用該功能會將該頁面傳送給另一部手機。你還可以發送聯繫人信息、方向導航，以及 Youtube 鏈接。當兩台手機放在一起時，屏幕顯示會縮小，點擊縮小的界面會發送相關信息。",-1))]),o[26]||(o[26]=e("p",null,"在安卓中，用户不允許刪除系統應用，以保證系統完整性。運營商和 OEM 利用該特性並開始將垃圾軟件放入系統分區，經常有一些沒用的應用存在系統中。安卓 4.0 允許用户禁用任何不能被卸載的應用，意味着該應用還存在於系統中但是不顯示在應用抽屜裏並且不能運行。如果用户願意深究設置項，這給了他們一個簡單的途徑來拿回手機的控制權。",-1)),e("p",null,[o[4]||(o[4]=t("安卓 4.0 可以看做是現代安卓時代的開始。大部分這時發佈的谷歌應用只能在安卓 4.0 及以上版本運行。4.0 還有許多谷歌想要好好利用的新 API——至少最初想要——對 4.0 以下的版本的支持就有限了。在冰淇淋三明治和蜂巢之後，谷歌真的開始認真對待軟件設計。在 2012 年 1 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/business/2012/01/google-launches-style-guide-for-android-developers/"},{default:p(()=>[...o[3]||(o[3]=[t("最終發佈了",-1)])]),_:1}),o[5]||(o[5]=t()),o[6]||(o[6]=e("em",null,"Android Design",-1)),o[7]||(o[7]=t("，一個教安卓開發者如何創建符合安卓外觀和感覺的應用的設計指南站點。這是 iOS 在有第三方應用支持開始就在做的事情，蘋果還嚴肅地對待應用的設計，不符合指南的應用都被 App Store 拒之門外。安卓三年以來谷歌沒有給出任何公共設計規範文檔的事實，足以説明事情有多糟糕。但隨着在 Duarte 掌控下的安卓設計革命，谷歌終於發佈了基本設計需求。",-1))]),o[27]||(o[27]=e("h3",{id:"google-play-和直接面向消費者出售設備的迴歸",tabindex:"-1"},[t("Google Play 和直接面向消費者出售設備的迴歸 "),e("a",{class:"header-anchor",href:"#google-play-和直接面向消費者出售設備的迴歸","aria-label":"Permalink to “Google Play 和直接面向消費者出售設備的迴歸”"},"​")],-1)),o[28]||(o[28]=e("p",null,"2012 年 3 月 6 日，谷歌將旗下提供的所有內容統一到 “Google Play”。安卓市場變為了 Google Play 商店，Google Books 變為 Google Play Books，Google Music 變為 Google Play Music，還有 Android Market Movies 變為 Google Play Movies & TV。儘管應用界面的變化不是很大，這四個內容應用都獲得了新的名稱和圖標。在 Play 商店購買的內容會下載到對應的應用中，Play 商店和 Play 內容應用一道給用户提供了易管理的內容體驗。",-1)),o[29]||(o[29]=e("p",null,"Google Play 更新是谷歌第一個大的更新週期外更新。四個自帶應用都沒有通過系統更新獲得升級，它們都是直接通過安卓市場/ Play 商店更新的。對單獨的應用啓用週期外更新是谷歌的重大關注點之一，而能夠實現這樣的更新，是自薑餅時代開始的工程努力的頂峯。谷歌一直致力於對應用從系統“解耦”，從而讓它們能夠通過安卓市場/ Play 商店進行分發。",-1)),o[30]||(o[30]=e("p",null,"儘管一兩個應用（主要是地圖和 Gmail）之前就在安卓市場上，從這裏開始你會看到許多更重大的更新，而其和系統發佈無關。系統更新需要 OEM 廠商和運營商的合作，所以很難保證推送到每個用户手上。而 Play 商店更新則完全掌握在谷歌手上，給了谷歌一條直接到達用户設備的途徑。因為 Google Play 的發佈，安卓市場對自身升級到了 Google Play Store，在那之後，圖書，音樂以及電影應用都下發了 Google Play 式的更新。",-1)),o[31]||(o[31]=e("p",null,"Google Play 系列應用的設計仍然不盡相同。每個應用的外觀和功能各有差異，但暫且來説，一個統一的品牌標識是個好的開始。從品牌標識中去除“安卓”字樣是很有必要的，因為很多服務是在瀏覽器中提供的，不需要安卓設備也能使用。",-1)),e("p",null,[o[9]||(o[9]=t("2012 年 4 月，谷歌",-1)),l(n,{href:"http://arstechnica.com/gadgets/2011/02/near-field-communications-a-technology-primer/"},{default:p(()=>[...o[8]||(o[8]=[t("再次開始通過 Play 商店銷售設備",-1)])]),_:1}),o[10]||(o[10]=t("，恢復在 Nexus One 發佈時嘗試的直接面向消費者銷售的方式。儘管距 Nexus One 銷售結束僅有兩年，但網上購物現在更加尋常，在接觸到物品之前就購買它並不像在 2010 年時聽起來那麼瘋狂。",-1))]),o[32]||(o[32]=e("p",null,"谷歌也看到了價格敏感的用户在面對 Nexus One 的 530 美元的價格時的反應。第一部銷售的設備是無鎖的，GSM 版本的 Galaxy Nexus，價格 399 美元。在那之後，價格變得更低。350 美元成為了最近兩台 Nexus 設備的入門價，7 英寸 Nexus 平板的價格更是隻有 200 美元到 220 美元。",-1)),o[33]||(o[33]=e("p",null,"今天，Play 商店銷售八款不同的安卓設備，四款 Chromebook，一款自動調温器，以及許多配件，設備商店已經是谷歌新產品發佈的實際地點了。新產品發佈總是如此受歡迎，站點往往無法承載如此大的流量，新 Nexus 手機也在幾小時內售空。",-1)),o[34]||(o[34]=e("hr",null,null,-1)),o[35]||(o[35]=e("p",null,[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[l(n,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...o[11]||(o[11]=[t("Ron Amadeo",-1)])]),_:1}),o[13]||(o[13]=t(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),l(n,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...o[12]||(o[12]=[t("@RonAmadeo",-1)])]),_:1})]),o[36]||(o[36]=e("hr",null,null,-1)),e("p",null,[o[15]||(o[15]=t("via: ",-1)),l(n,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/"},{default:p(()=>[...o[14]||(o[14]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/20/",-1)])]),_:1})]),e("p",null,[o[18]||(o[18]=t("譯者：",-1)),l(n,{href:"https://github.com/alim0x"},{default:p(()=>[...o[16]||(o[16]=[t("alim0x",-1)])]),_:1}),o[19]||(o[19]=t(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:p(()=>[...o[17]||(o[17]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[20]||(o[20]=[t("LCTT",-1)])]),_:1}),o[23]||(o[23]=t(" 原創翻譯，",-1)),l(n,{href:"http://linux.cn/"},{default:p(()=>[...o[21]||(o[21]=[t("Linux中國",-1)])]),_:1}),o[24]||(o[24]=t(" 榮譽推出",-1))])])}const b=r(u,[["render",m]]);export{x as __pageData,b as default};
